const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 100.01, F: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalFor = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('POST /orders creates an order: 201, json, id/items/total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
  assert.equal(typeof body.id, 'string')
})

test('total sums price*qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }]), 61)
})

test('total is floored to whole euros, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 25.5 is truncated to 25 (Math.floor), cents are lost.
  assert.equal(await totalFor([{ sku: 'B', qty: 1 }]), 25)
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 33)
})

test('no discount at or below 100', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount when raw total is above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180)  // 200 -> 180
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900) // 1000 -> 900
})

test('discount boundary and flooring after discount', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 100.01 is discounted to 90.009 then floored to 90,
  // so an order just over 100 is cheaper than one of exactly 100 (total 100) and a 101 order costs 90 (floor of 90.9).
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)
  assert.equal(await totalFor([{ sku: 'A', qty: 1 }, { sku: 'D', qty: 1 }, { sku: 'C', qty: 10 }]), 99) // 111 -> 99.9 -> 99
})

test('discount is a flat 10% on the whole order, no tiers for larger orders', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no extra tier for large orders; 10% from 100.01 up to any size.
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
  assert.equal(await totalFor([{ sku: 'F', qty: 7 }]), 209) // 233.31 -> 209.979 -> 209
})

test('unknown sku (pricing returns undefined) yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — price*qty is NaN, serialised as null, order still 201.
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('negative and zero quantities are accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation.
  assert.equal(await totalFor([{ sku: 'A', qty: -3 }]), -30)
  assert.equal(await totalFor([{ sku: 'A', qty: 0 }]), 0)
})

test('POST /orders rejects missing/empty/invalid items with 400', async () => {
  for (const [body, raw] of [[{}], [{ items: [] }], [{ items: 'x' }], [null, 'not json']]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods answer 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
